let current=null,code=new URLSearchParams(location.search).get('code')||sessionStorage.getItem('arenaCode')||'',files={},selected='',renderKey='',polling=false,busy=false,saveTimer=null,commandHistory=[],historyAt=0,consoleLines=[],admin=false,rooms=[];
