function time(ms){const s=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}.${Math.floor(ms%1000/100)}`;}
function notice(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.classList.remove('show'),4500);}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const b=await r.json();if(!r.ok){const e=new Error(b.error||'Erreur de connexion');e.status=r.status;throw e;}return b;}
function setClock(s){roomElapsedBase=s.room.elapsedMs;roomClockRunning=s.room.status==='running';elapsedBase=s.player?.elapsedMs??s.room.elapsedMs;syncedAt=Date.now();runningClock=s.room.status==='running'&&!s.player?.finishedAt;countdownUntil=s.room.startedAt&&s.room.elapsedMs===0?Date.now()+Math.max(0,s.room.startedAt-(s.serverNow||Date.now())):0;}
function clockValue(){return countdownUntil>Date.now()?0:elapsedBase+(runningClock?Math.max(0,Date.now()-Math.max(syncedAt,countdownUntil)):0);}
function remainingValue(){return current?.room?.timeLimitMs?Math.max(0,current.room.timeLimitMs-roomElapsedBase-(roomClockRunning?Math.max(0,Date.now()-Math.max(syncedAt,countdownUntil)):0)):0;}
function clockTick(){document.querySelectorAll('[data-remaining]').forEach(e=>e.textContent=time(remainingValue()));document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=time(clockValue()));const e=$('[data-countdown]');if(e)e.textContent=Math.max(1,Math.ceil((countdownUntil-Date.now())/1000));}
