function tourIllustration(kind){const art={server:'<span class="mini-server red">▰<br>▰<br>▰</span><span>→</span><span class="mini-server green">▰<br>▰<br>▰</span>',files:'<span class="mini-file">incident.log</span><span class="mini-file chosen">config.json ←</span>',edit:'<code>"enabled": <del>false</del> <b>true</b></code>',terminal:'<code>› set chemin valeur</code><kbd>Entrée ↵</kbd>',bot:'<span class="mini-bot">H ♥</span><span class="mini-bubble">Un réglage à la fois !</span>',check:'<span class="mini-test">Redémarrer le service</span><span class="green">✓ En ligne</span>'};return '<div class="tour-illustration" aria-hidden="true">'+art[kind]+'</div>';}
function positionTour(){if(!tourActive)return;const step=tourSteps[tourStep],target=$(step.target),overlay=$('#player-tour'),spot=overlay.querySelector('.tour-spotlight'),card=$('#tour-content');if(!target||!spot)return;const r=target.getBoundingClientRect(),gap=12,w=globalThis.innerWidth||document.documentElement.clientWidth,h=globalThis.innerHeight||document.documentElement.clientHeight;const top=Math.max(8,r.top-5),bottom=Math.min(h-8,r.bottom+5),left=Math.max(8,r.left-5),right=Math.min(w-8,r.right+5);Object.assign(spot.style,{top:top+'px',left:left+'px',width:Math.max(0,right-left)+'px',height:Math.max(0,bottom-top)+'px'});const ch=card.offsetHeight,cw=card.offsetWidth;let x=Math.max(12,Math.min(left,w-cw-12)),y=bottom+gap;if(y+ch>h-12){if(top-ch-gap>=12)y=top-ch-gap;else if(right+gap+cw<=w-12){x=right+gap;y=Math.max(12,Math.min(top,h-ch-12));}else if(left-gap-cw>=12){x=left-gap-cw;y=Math.max(12,Math.min(top,h-ch-12));}else{const visible=Math.max(40,Math.min(bottom-top,h-ch-36));const newTop=Math.max(8,Math.min(top,h-ch-visible-24));Object.assign(spot.style,{top:newTop+'px',height:visible+'px'});y=newTop+visible+gap;}}Object.assign(card.style,{top:Math.max(12,y)+'px',left:x+'px'});}
function showTour(index=0){const overlay=$('#player-tour');if(!overlay)return;if(!tourActive){tourPreviousPane=activeWorkbench;tourPreviousFocus=document.activeElement;}tourActive=true;tourStep=index;const step=tourSteps[index];if(step.pane)workspacePane(step.pane);document.querySelectorAll('.tour-target').forEach(e=>e.classList.remove('tour-target'));const target=$(step.target);target?.classList.add('tour-target');overlay.hidden=false;$('#tour-content').innerHTML=`<p class="eyebrow">DÉCOUVRIR LE POSTE · ${index+1} / ${tourSteps.length}</p><h2>${step.title}</h2>${tourIllustration(step.illustration)}<p>${step.text}</p><div class="tour-actions"><button type="button" class="text-button" id="tour-skip">Passer</button>${index?'<button type="button" class="secondary" id="tour-back">Retour</button>':''}<button type="button" class="primary" id="tour-next">${index===tourSteps.length-1?'Jouer !':'Suivant →'}</button></div>`;$('#tour-skip').onclick=closeTour;const back=$('#tour-back');if(back)back.onclick=()=>showTour(index-1);$('#tour-next').onclick=()=>index===tourSteps.length-1?closeTour():showTour(index+1);overlay.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeTour();}if(e.key==='Tab'){const buttons=Array.from(overlay.querySelectorAll('button')),i=buttons.indexOf(document.activeElement);if(e.shiftKey&&(i<=0)){e.preventDefault();buttons.at(-1)?.focus();}else if(!e.shiftKey&&i===buttons.length-1){e.preventDefault();buttons[0]?.focus();}}};target?.scrollIntoView({block:'center',behavior:'instant'});positionTour();$('#tour-next').focus({preventScroll:true});}
function closeTour(){sessionStorage.setItem('arenaTour:v2','seen');tourActive=false;$('#player-tour').hidden=true;document.querySelectorAll('.tour-target').forEach(e=>e.classList.remove('tour-target'));workspacePane(tourPreviousPane);if(tourPreviousFocus?.isConnected)tourPreviousFocus.focus({preventScroll:true});}
function maybeShowTour(){if(tourActive){showTour(tourStep);return;}if(!sessionStorage.getItem('arenaTour:v2')&&current?.room.status==='running')showTour(0);}
async function refreshLobby(){
 const input=$('#join-code');if(!input||input.value.trim().length!==6)return;
 try{const lobby=await api('/api/lobby?code='+encodeURIComponent(input.value.trim()));const field=$('#team-field');field.hidden=lobby.mode!=='teams';field.querySelector('input').required=lobby.mode==='teams';$('#team-options').innerHTML=lobby.teams.map(t=>`<option value="${escape(t.name)}">${t.count}/4 membres</option>`).join('');$('#team-capacity').textContent=lobby.mode==='teams'?`${lobby.teams.length} équipes · aucun plafond de groupes · saisis un nom existant pour rejoindre, ou un nouveau nom pour créer.`:'';}catch{}
}
function datacenterSelector(s){const count=s.player.completedCount??s.player.stage;return `<section class="system-visual selectable-datacenter" aria-label="Datacenter : choisir un serveur"><div class="system-title"><span class="eyebrow">LE DATACENTER REPREND VIE</span><strong class="datacenter-percent">${count*25}% RÉTABLI</strong></div><div class="station-path system-nodes">${stationPath(s)}</div><div class="system-service ${count===4?'online':''}"><span class="live-dot"></span> CAMPUS API <b>${count===4?'SERVICE RÉTABLI':'RESTAURATION EN COURS'}</b></div></section>`;}
function stationPath(s){const team=!!s.player.teamId;return platforms.map((p,i)=>{const done=team?s.player.completedStages.includes(i):i<s.player.stage,active=i===s.player.stage,available=team||active;return `<button type="button" ${team?'data-station="'+i+'"':''} class="system-node server-pick ${done?'online':'repairing'} ${active?'selected':''}" aria-pressed="${active}" ${available?'':'disabled'} aria-label="${p} · ${done?'en ligne':available?'ouvrir ce serveur':'verrouillé'}"><div class="node-cabinet">${[0,1,2].map(()=>'<div class="node-blade"><span></span><i></i><i></i></div>').join('')}</div><b>${p}</b><small>${done?'EN LIGNE ✓':active?'TON POSTE':team?'À RÉPARER':'VERROUILLÉ'}</small>${i<3?'<span class="packet-link '+((team?(s.player.verifiedLinks||[]).includes(i):done&&i+1<s.player.stage)?'link-online':'')+'" aria-hidden="true"><i></i><i></i></span>':''}</button>`;}).join('');}
function syncSharedFiles(s){
 if(!s.player?.teamId||current?.player?.id!==s.player.id||current.player.stage!==s.player.stage)return;
 if(!hasDraft&&!saving&&!conflicted&&s.player.version>baseVersion){baseVersion=s.player.version;files={...s.player.files};if($('#file-editor'))selectFile(selected);if($('#save-state'))$('#save-state').textContent='SYNCHRONISÉ';log('Fichier partagé actualisé'+(s.player.lastEditor?' par '+s.player.lastEditor:'')+'.','system');}
}
function updateTeamChrome(s){
 if(!s.player?.teamId)return;const p=s.player;
 const path=$('.station-path');if(path&&path.dataset.completed!==p.completedStages.join(',')){path.innerHTML=stationPath(s);path.dataset.completed=p.completedStages.join(',');}
 const percent=$('.datacenter-percent');if(percent)percent.textContent=p.completedCount*25+'% RÉTABLI';const service=$('.selectable-datacenter .system-service');if(service){service.classList.toggle('online',p.completedCount===4);service.innerHTML='<span class="live-dot"></span> CAMPUS API <b>'+(p.completedCount===4?'SERVICE RÉTABLI':'RESTAURATION EN COURS')+'</b>';}const roster=$('#team-roster');if(roster)roster.innerHTML=`<section class="team-roster"><b>ÉQUIPE ${escape(p.teamName)} · ${p.completedCount}/4</b><p>Les quatre postes sont accessibles en parallèle. Clique un serveur en haut pour le rejoindre.</p>${p.members.map(m=>`<div>${avatarMark(m.avatar,'mini')}<span>${escape(m.name)}${m.id===p.creatorId?' · créateur':''}${m.id===p.id?' · toi':''}<small>${m.online?'● Connecté':'○ Hors ligne'} · ${platforms[m.activeStation??m.assignedStation]}</small></span></div>`).join('')}<p>Fichiers synchronisés · la dernière validation des 4 postes termine votre course.</p></section>`;
 const visual=$('.visual-rail .system-visual');if(visual&&visual.dataset.completed!==p.completedStages.join(',')){const wrap=document.createElement('div');wrap.innerHTML=systemVisual(p.completedCount,p.completedStages);const next=wrap.firstElementChild;next.dataset.completed=p.completedStages.join(',');visual.replaceWith(next);}
 const button=$('#validate-button');if(button){button.disabled=!!p.stationDone;button.innerHTML=p.stationDone?'Poste rétabli ✓':'Tester la réparation <span>↗</span>';}
 const editor=$('#file-editor');if(editor)editor.readOnly=!!p.stationDone||!current.workspace?.editable.includes(selected)||s.room.status!=='running';
 showConflict();
}
function showConflict(){const el=$('#shared-conflict');if(el)el.hidden=!conflicted;}
