 clearTimeout(saveTimer);try{const s=await api('/api/state?code='+encodeURIComponent(code)+'&station='+teamStation);hasDraft=false;conflicted=false;files={};baseVersion=s.player.version;renderState(s,true);notice('Version partagée chargée.');}catch(err){notice(err.message);}
