 $('#player-ranking-content').innerHTML=`<p class="eyebrow">${s.player?.teamId?'CLASSEMENT DE TON ÉQUIPE':'TON CLASSEMENT'}</p><h2>${pos?ordinal:'—'} <span>/ ${s.leaderboard.length}</span></h2><p class="ranking-name">${escape(s.player?.teamName||s.player?.name||'')}</p><p>${own?.finishedAt?'Arrivée enregistrée · '+time(own.elapsedMs):'Position provisoire selon la progression ; les ex æquo sont affichés par nom.'}</p><div class="board">${leaderboardHTML(s,true)}</div>`;
