function avatarPicker(name,initial){return `<fieldset class="avatar-picker" data-avatar-picker><legend>${name==='hostAvatar'?'AVATAR DE L’HÔTE':'CHOISIS TON AVATAR'}</legend><input type="hidden" name="${name}" value="${initial}"><div>${AVATARS.map(a=>`<button type="button" data-avatar="${a.id}" aria-label="${a.label}" aria-pressed="${a.id===initial}">${a.emoji}</button>`).join('')}</div></fieldset>`;}
function bindAvatarPickers(root){root.querySelectorAll('[data-avatar-picker]').forEach(group=>{const input=group.querySelector('input');group.querySelectorAll('button').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.avatar===input.value));button.onclick=()=>{input.value=button.dataset.avatar;group.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));};});});}
function systemVisual(stage,completedStages){const restored=i=>completedStages?completedStages.includes(i):stage>i;return `<section class="system-visual" aria-label="Infrastructure : ${stage} systèmes rétablis sur 4"><div class="system-title"><span class="eyebrow">LE DATACENTER REPREND VIE</span><strong>${stage*25}% RÉTABLI</strong></div><div class="system-nodes">${platforms.map((p,i)=>`<div class="system-node ${restored(i)?'online':completedStages?'repairing':stage===i?'repairing':'offline'}"><div class="node-cabinet">${[0,1,2].map(()=>'<div class="node-blade"><span></span><i></i><i></i></div>').join('')}</div><b>${p}</b><small>${restored(i)?'EN LIGNE':completedStages?'À RÉPARER':stage===i?'EN RÉPARATION':'HORS LIGNE'}</small>${i<3?'<div class="packet-link"><i></i><i></i></div>':''}</div>`).join('')}</div><div class="system-service ${stage===4?'online':''}"><span class="live-dot"></span> CAMPUS API <b>${stage===4?'SERVICE RÉTABLI':'RESTAURATION EN COURS'}</b></div></section>`;}
function leaderSpotlight(lead,status){const winners=lead.players;const label=lead.kind==='winner'?'PREMIER À TERMINER':lead.kind==='leading'?(winners.length>1?'TÊTE DE COURSE PARTAGÉE':'EN TÊTE DE LA COURSE'):status==='waiting'?'LES OPÉRATEURS SE PRÉPARENT':'TOUT RESTE À JOUER';return `<section class="leader-spotlight ${lead.kind==='winner'?'winner':''}"><div class="leader-avatars">${winners.slice(0,4).map(p=>avatarMark(p.avatar)).join('')||'<span class="avatar">🏁</span>'}</div><div><p class="eyebrow">${label}</p><h2>${lead.kind==='start'?'Qui rétablira le datacenter ?':escape(winners.slice(0,3).map(p=>p.name).join(' · '))}${lead.kind!=='start'&&winners.length>3?' + '+(winners.length-3):''}</h2><p>${lead.kind==='winner'?time(winners[0].elapsedMs)+' · 4 missions validées':lead.kind==='leading'?lead.stage+'/4 missions validées · '+(winners.length>1?'ex æquo en progression':'la course continue'):'Le classement se départage dès la première réparation.'}</p></div>${lead.kind==='winner'?'<span class="winner-crown" aria-label="Victoire">🏆</span>':''}</section>`;}
function celebrate(text){const el=document.createElement('div');el.className='repair-celebration';el.setAttribute('role','status');el.innerHTML=`<div class="celebration-ring">✓</div><b>${escape(text)}</b><div class="sparks">${Array.from({length:8},()=>'<i></i>').join('')}</div>`;document.body.append(el);setTimeout(()=>el.remove(),2200);}
rememberRoom(code);
document.addEventListener('click',e=>{const a=e.target.closest('a[data-room-link]');if(a)rememberRoom(a.dataset.roomLink);});
try{admin=(await api('/api/session')).admin;}catch{}
configureNavigation();
document.addEventListener('click',e=>{if(e.target.closest('[data-show-ranking]'))showPlayerRanking();});
globalThis.addEventListener?.('resize',positionTour);document.addEventListener('scroll',positionTour,true);
$('#player-ranking-close').onclick=()=>$('#player-ranking').close();
$('#help-button').onclick=()=>$('#guide').showModal();$('.dialog-close').onclick=()=>$('#guide').close();
if(location.pathname==='/admin'){await adminRefresh(true);if(admin)startAdminPoll();}else if(location.pathname==='/board')await boardPage();else{joinScreen();if(code){await poll();startPolling();}}
